def sum_left_leaves(root):
    total = 0
    stack = [(root, False)]
    while stack:
        node, is_left = stack.pop()
        if node is None:
            continue
        if is_left and node.left is None and node.right is None:
            total += node.val
        stack.append((node.left, True))
        stack.append((node.right, False))
    return total

